function mapH(h){
 if(!h||h.charAt(0)!=='#'||h==='#main')return h;
 var k=h.replace(/^#\//,''),m;
 if(k===''||k==='about'||k==='privacy')return h;
 if(/^(explain|watch|kg|sa|grade|videos|unit|practice|course)\//.test(k))return h;
 if(k==='courses')return '#/courses';
 if(RT2[k+'.html'])return RT2[k+'.html'];
 if(m=/^unit-(.+)$/.exec(k))return '#/unit/'+m[1];
 if(m=/^teach-(.+)$/.exec(k))return '#/explain/teach-'+m[1];
 if(m=/^kg([12])\/(.+)$/.exec(k))return '#/kg/'+m[1]+'/u/'+m[2];
 if(m=/^kg([12])-u(\d)-practice$/.exec(k))return '#/kg/'+m[1]+'/practice/'+m[2];
 if(m=/^kg([12])-unit\/(.+)$/.exec(k))return '#/kg/'+m[1]+'/u/'+m[2];
 return '#/page/'+k+'.html';
}
function href(x,def){var h=x[3];return h?E(mapH(h)):(def||'#')}
function ext(x){return /^https?:/.test(x[3]||'')?' target="_blank" rel="noopener"':''}
function render(id){
 var it=PG[id],o='',i=0,card=null;
 function close(){if(card){o+='</div>';if(card==='sc'||card==='gc'){} card=null}}
 var grid=null;
 function opengrid(t){if(grid!==t){closegrid();o+='<div class="ds-list ds-list--cols">';grid=t}}
 function closegrid(){if(grid){close();o+='</div>';grid=null}}
 function btns(open){return open}
 var act=false;
 function actopen(){if(!act){o+='<div class="ds-actions">';act=true}}
 function actclose(){if(act){o+='</div>';act=false}}
 var crumbs=false;
 for(;i<it.length;i++){var x=it[i],k=x[0];
  if(k!=='ca'&&k!=='cs'&&crumbs){o+='</nav>';crumbs=false}
  if(k!=='gcb'&&k!=='gcb2'&&k!=='fpb'&&k!=='fpb2')actclose();
  if(k==='skip'){o+='<a class="ds-sr" href="#main">'+T(x)+'</a>';continue}
  if(k==='ca'||k==='cs'){if(!crumbs){o+='<nav class="ds-crumbs ds-crumbs--full" aria-label="'+E(__t('مسار الصفحة','Breadcrumbs'))+'">';crumbs=true}
   o+=(k==='ca'?'<a href="#/">'+T(x)+'</a>':'<span>'+T(x)+'</span>');continue}
  if(k==='back'){closegrid();o+='<a class="ds-back" href="'+href(x)+'">'+DS.icon('back')+'<span>'+T(x)+'</span></a>';continue}
  if(k==='tag'){closegrid();o+='<span class="ds-tag">'+T(x)+'</span>';continue}
  if(k==='h1'){closegrid();o+='<h1>'+T(x)+'</h1>';continue}
  if(k==='lead'||k==='sub'){closegrid();o+='<p class="ds-sub">'+T(x)+'</p>';continue}
  if(k==='h2'){closegrid();o+='<h2>'+T(x)+'</h2>';continue}
  if(k==='p'){closegrid();o+='<p>'+T(x)+'</p>';continue}
  if(k==='pl'){closegrid();o+='<p><a class="ds-link" href="'+href(x)+'"'+ext(x)+'>'+T(x)+'</a></p>';continue}
  if(k==='geh'){closegrid();o+='<div class="ds-card ds-empty"><h2>'+T(x)+'</h2>';card='ge';continue}
  if(k==='gep'){o+='<p>'+T(x)+'</p></div>';card=null;continue}
  if(k==='gcc'){opengrid('gc');close();o+='<div class="ds-card ds-ucard"><span class="ds-tag">'+T(x)+'</span>';card='gc';continue}
  if(k==='gct'){o+='<h3>'+T(x)+'</h3>';continue}
  if(k==='gcn'){o+='<p>'+T(x)+'</p>';continue}
  if(k==='gcb'||k==='gcb2'){actopen();o+='<a class="ds-btn'+(k==='gcb2'?' ds-btn--soft':'')+'" href="'+href(x)+'"'+ext(x)+'>'+T(x)+'</a>';continue}
  if(k==='scn'){opengrid('sc');close();o+='<div class="ds-card ds-ucard"><span class="ds-tile">'+T(x)+'</span>';card='sc';continue}
  if(k==='sce'){o+='<span class="ds-tag">'+T(x)+'</span>';continue}
  if(k==='sch'){o+='<h3>'+T(x)+'</h3>';continue}
  if(k==='scp'){o+='<p>'+T(x)+'</p>';continue}
  if(k==='scl'){o+='<a class="ds-btn ds-btn--soft" href="'+href(x)+'"'+ext(x)+'>'+T(x)+'</a>';continue}
  if(k==='fpt'){closegrid();o+='<section class="ds-card"><span class="ds-tag">'+T(x)+'</span>';card='fp';continue}
  if(k==='fph'){o+='<h2>'+T(x)+'</h2>';continue}
  if(k==='fpp'){o+='<p>'+T(x)+'</p>';continue}
  if(k==='fpb'||k==='fpb2'){actopen();o+='<a class="ds-btn'+(k==='fpb2'?' ds-btn--soft':'')+'" href="'+href(x)+'"'+ext(x)+'>'+T(x)+'</a>';continue}
  if(k==='b'||k==='b2'){closegrid();o+='<a class="ds-btn'+(k==='b2'?' ds-btn--soft':'')+'" href="'+href(x)+'"'+ext(x)+'>'+T(x)+'</a>';continue}
  if(k==='f')break;
 }
 actclose();if(crumbs)o+='</nav>';closegrid();close();
 // footer
 var f=it.slice(i),parts=[];
 function push(t,h){var l=parts[parts.length-1];if(l&&l[0]===t&&(t==='btn'||t==='chip'))l[1]+=h;else parts.push([t,h])}
 for(var j=0;j<f.length;j++){var y=f[j],u=y[3]||'';
  if(/facebook\.com|instagram|tiktok|youtube/.test(u)&&/(Facebook|Instagram|TikTok|YouTube)\b/.test(y[2])&&y[2].indexOf('Follow')<0) push('chip','<a class="ds-chip" href="'+E(u)+'" target="_blank" rel="noopener">'+T(y)+'</a>');
  else if(/Qarajah/.test(y[2])) push('x','<div class="ds-addr">'+PINI+'<span class="ds-sr">\ud83d\udccd </span><span>'+T(y)+'</span></div>');
  else if(/^tel:/.test(u)) push('x','<div><a class="ds-link" dir="ltr" href="'+E(u)+'">'+T(y)+'</a></div>');
  else if(/wa\.me/.test(u)&&/جروب|group/i.test(y[1]+y[2])) push('chip','<a class="ds-chip" href="'+(DS.links&&DS.links.waGroup||E(u))+'" target="_blank" rel="noopener">'+T(y)+'</a>');
  else if(u) push(/wa\.me|facebook/.test(u)?'btn':'chip',(/wa\.me|facebook/.test(u)?'<a class="ds-btn'+(/facebook/.test(u)?' ds-btn--soft':'')+'" href="'+E(u)+'" target="_blank" rel="noopener">':'<a class="ds-chip" href="'+href(y)+'">')+T(y)+'</a>');
  else push('x','<p>'+T(y)+'</p>');
 }
 var fh='';parts.forEach(function(p){fh+=p[0]==='btn'?'<div class="ds-actions">'+p[1]+'</div>':p[0]==='chip'?'<div class="ds-chips">'+p[1]+'</div>':p[1]});
 o+='<section class="ds-card ds-foot-card">'+fh+'</section>';
 return o}
